P: int = 23
G: int = 2

def smul(a: int, point: int) -> int:
    return (a * point) % R

def pair(left: int, right: int) -> int:
    return pow(G, (left * right) % R, P)

def run() -> None:
    total = 0
    for a in range(R):
        for b in range(R):
            for x in range(R):
                for y in range(R):
                    assert pair(smul(a, x), smul(b, y)) == pow(pair(x, y), a * b, P)
                    total += 1
    print(f"Verified {total:,} bilinear identities in the exponent model.")

if __name__ == "__main__":
    run()

